query:
SELECT ?item ?label ?sitelinks (GROUP_CONCAT(DISTINCT ?alias; separator="|") AS ?aliases) WHERE {
  { SELECT DISTINCT ?item WHERE { { ?item wdt:P131* wd:Q1186 } UNION { ?item wdt:P131* wd:Q1185 } hint:Prior hint:runFirst true . ?item wdt:P31/wdt:P279* wd:Q842402 . } LIMIT 20000 } hint:Prior hint:runFirst true .
  ?item wikibase:sitelinks ?sitelinks .
  ?item rdfs:label ?label . FILTER(LANG(?label) = "en")
  OPTIONAL { ?item skos:altLabel ?alias . FILTER(LANG(?alias) = "en") }
} GROUP BY ?item ?label ?sitelinks
